# =====================================================================
# SIMPLE ROAD GRAPH (same district or within ~80 km)
# =====================================================================
def haversine(lat1, lon1, lat2, lon2):
    R = 6371.0
    dlat = math.radians(lat2 - lat1)
    dlon = math.radians(lon2 - lon1)
    a = (math.sin(dlat / 2) ** 2 +
         math.cos(math.radians(lat1)) * math.cos(math.radians(lat2)) *
         math.sin(dlon / 2) ** 2)
    return 2 * R * math.asin(math.sqrt(min(1.0, a)))


GRAPH = {}
for i, p1 in enumerate(PLACES):
    k1 = (p1["district"], p1["name"])
    for p2 in PLACES[i + 1:]:
        dist = haversine(p1["lat"], p1["lon"], p2["lat"], p2["lon"])
        if dist < 80 or p1["district"] == p2["district"]:
            k2 = (p2["district"], p2["name"])
            GRAPH.setdefault(k1, []).append((k2, dist))
            GRAPH.setdefault(k2, []).append((k1, dist))


