def chip(level, text=None):
    name, label, color = LEVELS[level]
    fg = "#3b2f00" if level == 1 else "#ffffff"
    return f'<span class="sb-chip" style="background:{color};color:{fg}">{text or name}</span>'


# =====================================================================
# RISK ANALYSIS
# =====================================================================
def analyse(d):
    daily = d["daily"]
    elev = d.get("elevation", 500) or 500
    rain = [(r or 0) for r in daily["precipitation_sum"]]
    past3 = sum(rain[:3])
    next3 = sum(rain[3:6])
    next7 = sum(rain[3:10])
    peak = max(rain[3:6])
    codes = daily["weather_code"][3:6]
    severe = any(c in SEVERE_CODES for c in codes)

    terrain = 0.6 if elev < 350 else (1.0 if elev < 1000 else 1.3)
    terrain_name = (
        "flat / plains" if elev < 350
        else ("mid hills" if elev < 1000 else "steep high hills")
    )

    index = (0.5 * past3 + next3) * terrain
    level = 0 if index < 25 else 1 if index < 60 else 2 if index < 120 else 3

    if terrain >= 1.0 and peak >= 115.6:
        level = 3
    elif terrain >= 1.0 and peak >= 64.5:
        level = max(level, 2)
    if severe:
        level = max(level, 1)

    reasons = [
        f"Rain in the last 3 days: <b>{past3:.0f} mm</b> (wet soil is more likely to slide)",
        f"Forecast rain in the next 3 days: <b>{next3:.0f} mm</b> (next 7 days: {next7:.0f} mm)",
        f"Heaviest day in the next 3 days: <b>{peak:.0f} mm</b>",
        f"Terrain: <b>{terrain_name}</b> ({elev:.0f} m above sea level)"
    ]
    if severe:
        reasons.append("Thunderstorm / very heavy rain or snow in the forecast")

    return dict(
        level=level, index=index, past3=past3, next3=next3, next7=next7,
        peak=peak, elev=elev, terrain=terrain, terrain_name=terrain_name,
        severe=severe, reasons=reasons,
    )


