API = "https://api.open-meteo.com/v1/forecast"
_cache = {"ok": False, "t": 0}


def load_data():
    if _cache["ok"] and time.time() - _cache["t"] < 1800:
        return

    for i in range(0, len(PLACES), 20):
        chunk = PLACES[i:i + 20]
        r = requests.get(
            API,
            params={
                "latitude": ",".join(str(p["lat"]) for p in chunk),
                "longitude": ",".join(str(p["lon"]) for p in chunk),
                "current": "temperature_2m,apparent_temperature,relative_humidity_2m,wind_speed_10m,"
                           "wind_gusts_10m,precipitation,weather_code,pressure_msl,cloud_cover",
                "daily": "weather_code,temperature_2m_max,temperature_2m_min,precipitation_sum,"
                         "precipitation_probability_max,wind_gusts_10m_max,sunrise,sunset,uv_index_max",
                "past_days": 3,
                "forecast_days": 7,
                "timezone": "auto",
            },
            timeout=40
        )
        r.raise_for_status()
        data = r.json()
        if isinstance(data, dict):
            data = [data]
        for p, d in zip(chunk, data):
            p["wx"] = d
            p["risk"] = analyse(d)

    _cache.update(ok=True, t=time.time())


def nearest_place(la, lo):
    return min(PLACES, key=lambda p: (p["lat"] - la) ** 2 + (p["lon"] - lo) ** 2)


