def travel_notes(p):
    d = p["wx"]["daily"]
    cur = p["wx"]["current"]
    r = p["risk"]
    notes = []
    codes = d["weather_code"][3:6]

    if any(c in {95, 96, 99} for c in codes):
        notes.append("⛈️ Thunderstorms expected - avoid open ridges, riverbeds and waterfalls.")
    if any(c in FOG_CODES for c in codes):
        notes.append("🌫️ Fog may reduce visibility on mountain roads - use fog lights and drive slowly.")
    gust = max((g or 0) for g in d["wind_gusts_10m_max"][3:6])
    if gust >= 50:
        notes.append(f"💨 Strong gusts up to {gust:.0f} km/h - be careful near cliffs and tall trees.")
    tmin = min(d["temperature_2m_min"][3:6])
    if r["elev"] > 1800 and tmin <= 2:
        notes.append(f"🧊 Very cold nights ({tmin}°C) - possible ice or snow on high roads; carry warm clothes.")
    tmax = max(d["temperature_2m_max"][3:6])
    if tmax >= 38:
        notes.append(f"🥵 Hot days up to {tmax}°C - carry water and avoid travelling in peak afternoon heat.")
    if p["district"] in ("Chamoli", "Rudraprayag", "Uttarkashi") and r["level"] >= 1:
        notes.append("🛕 Char Dham route area - check yatra advisories and road status before moving.")
    if r["level"] >= 2:
        notes.append("📞 Emergency: dial 112. Check the local district administration for road-closure updates.")
    if not notes:
        notes.append("👍 No special weather warnings for the next 3 days.")
    return notes


def day_level(rain_mm, terrain):
    v = rain_mm * terrain
    return 0 if v < 15 else 1 if v < 40 else 2 if v < 80 else 3


# =====================================================================
# ROUTE HELPERS
# =====================================================================
def point_to_segment_km(px, py, ax, ay, bx, by):
    scale_y = 111.0
    scale_x = 111.0 * math.cos(math.radians((ay + by) / 2))
    pxk, pyk = px * scale_x, py * scale_y
    axk, ayk = ax * scale_x, ay * scale_y
    bxk, byk = bx * scale_x, by * scale_y
    dx, dy = bxk - axk, byk - ayk
    if dx == 0 and dy == 0:
        return math.hypot(pxk - axk, pyk - ayk)
    t = max(0.0, min(1.0, ((pxk - axk) * dx + (pyk - ayk) * dy) / (dx * dx + dy * dy)))
    return math.hypot(pxk - (axk + t * dx), pyk - (ayk + t * dy))


def dijkstra(start, end, cost_fn):
    pq = [(0.0, start, [start])]
    best = {start: 0.0}
    while pq:
        cost, node, path = heapq.heappop(pq)
        if node == end:
            return path, cost
        if cost > best.get(node, float("inf")):
            continue
        for neigh, dist in GRAPH.get(node, []):
            c = cost_fn(node, neigh, dist)
            new_cost = cost + c
            if new_cost < best.get(neigh, float("inf")):
                best[neigh] = new_cost
                heapq.heappush(pq, (new_cost, neigh, path + [neigh]))
    return None, float("inf")


def find_route_options(orig_key, dest_key):
    if orig_key == dest_key:
        return []

    def cost_dist(u, v, d): return d
    def cost_risk(u, v, d): return d * (1.0 + 1.8 * INDEX[v]["risk"]["level"])
    def cost_balanced(u, v, d): return d * (1.0 + 0.9 * INDEX[v]["risk"]["level"]) + 8.0 * INDEX[v]["risk"]["level"]

    candidates = []
    seen = set()

    for name, fn in [
        ("Shortest distance", cost_dist),
        ("Lowest risk preference", cost_risk),
        ("Balanced", cost_balanced),
    ]:
        path, _ = dijkstra(orig_key, dest_key, fn)
        if path is None:
            continue
        key = tuple(path)
        if key in seen:
            continue
        seen.add(key)

        places = [INDEX[k] for k in path]
        levels = [p["risk"]["level"] for p in places]
        max_lv = max(levels)
        avg_lv = sum(levels) / len(levels)
        total_km = sum(haversine(a["lat"], a["lon"], b["lat"], b["lon"]) for a, b in zip(places, places[1:]))

        warnings = []
        for hname, hdist, hlat, hlon, hbase in HOTSPOTS:
            for a, b in zip(places, places[1:]):
                if point_to_segment_km(hlon, hlat, a["lon"], a["lat"], b["lon"], b["lat"]) < 18:
                    warnings.append(f"Near known hotspot: {hname} (usual susceptibility: {hbase})")
                    break
        high_places = [p["name"] for p in places if p["risk"]["level"] >= 2]
        if high_places:
            warnings.append("Higher current risk towns on this path: " + ", ".join(high_places))

        candidates.append({
            "label": name,
            "path": path,
            "places": places,
            "max_lv": max_lv,
            "avg_lv": avg_lv,
            "km": total_km,
            "warnings": warnings,
            "score": (max_lv, avg_lv, total_km),
        })

    candidates.sort(key=lambda r: r["score"])
    return candidates[:3]


def mapbox_road_route(places):
    """
    Fetch a real, road-following driving route through the given ordered list of
    place dicts (each with 'lat'/'lon'), using the Mapbox Directions API.
    Returns (geometry_coords, road_km, road_minutes) or (None, None, None) if
    unavailable (no token, API error, or no route found).
    """
    if not MAPBOX_TOKEN or len(places) < 2:
        return None, None, None
    coords = ";".join(f"{p['lon']},{p['lat']}" for p in places)
    url = f"https://api.mapbox.com/directions/v5/mapbox/driving/{coords}"
    try:
        r = requests.get(
            url,
            params={
                "geometries": "geojson",
                "overview": "full",
                "access_token": MAPBOX_TOKEN,
            },
            timeout=20,
        )
        r.raise_for_status()
        data = r.json()
        if data.get("code") != "Ok" or not data.get("routes"):
            return None, None, None
        route = data["routes"][0]
        geom = route["geometry"]["coordinates"]
        km = route["distance"] / 1000.0
        minutes = route["duration"] / 60.0
        return geom, km, minutes
    except Exception:
        return None, None, None


def route_report_html(orig_key, dest_key, routes):
    o = INDEX[orig_key]
    d = INDEX[dest_key]

    header = (
        '<div class="sb-banner sb-banner-dark">'
        '<div class="sb-banner-s">Origin → Destination</div>'
        f'<div class="sb-banner-t">{H.escape(o["name"])} ({H.escape(o["district"])}) &nbsp;→&nbsp; '
        f'{H.escape(d["name"])} ({H.escape(d["district"])})</div>'
        '<div class="sb-banner-n">Routes are ranked by current rainfall-based landslide risk + known hotspots. '
        'Where available, the line follows real roads (via Mapbox Directions); otherwise it shows a straight '
        'line between towns. Always verify actual road status.</div></div>'
    )

    if not routes:
        return '<div class="sb-stack">' + header + (
            '<div class="sb-warnbox">No route found in the town graph. '
            'Try nearby major towns or check district roads manually.</div></div>'
        )

    cards = ""
    for rank, r in enumerate(routes, 1):
        color = LEVELS[r["max_lv"]][2]
        title, advice = TRAVEL[r["max_lv"]]
        town_chips = ' <span class="sb-arrow">→</span> '.join(
            f'{H.escape(p["name"])} {chip(p["risk"]["level"])}' for p in r["places"]
        )
        if r["warnings"]:
            warn_html = (
                '<div class="sb-sub" style="margin-top:10px">⚠️ Warnings</div><ul class="sb-ul">'
                + "".join(f"<li>{H.escape(w)}</li>" for w in r["warnings"])
                + "</ul>"
            )
        else:
            warn_html = '<div class="sb-ok">👍 No known landslide hotspots detected close to this path.</div>'

        if r.get("road_km") is not None:
            hrs = int(r["road_min"] // 60)
            mins = int(round(r["road_min"] % 60))
            time_str = f'{hrs}h {mins}m' if hrs else f'{mins} min'
            dist_line = (
                f'🛣️ Road distance: {r["road_km"]:.0f} km &nbsp;·&nbsp; '
                f'Est. driving time: {time_str} &nbsp;·&nbsp; '
                f'Max risk: {LEVELS[r["max_lv"]][0]} &nbsp;·&nbsp; Avg risk: {r["avg_lv"]:.1f}'
            )
        else:
            dist_line = (
                f'Approx. straight-line distance: {r["km"]:.0f} km (road distance unavailable) '
                f'&nbsp;·&nbsp; Max risk: {LEVELS[r["max_lv"]][0]} &nbsp;·&nbsp; Avg risk: {r["avg_lv"]:.1f}'
            )

        cards += (
            f'<div class="sb-panel" style="border-left:6px solid {color}">'
            f'<div class="sb-panel-h"><span>#{rank} &nbsp;{r["label"]}</span>{chip(r["max_lv"])}</div>'
            f'<div class="sb-meta">{dist_line}</div>'
            f'<div class="sb-path">{town_chips}</div>'
            f'<div class="sb-sub" style="margin-top:12px">🧳 {title}</div>'
            f'<p class="sb-p">{advice}</p>'
            f'{warn_html}</div>'
        )

    note = (
        '<p class="sb-note">Routes are generated from a simplified town-to-town graph (same district or within ~80 km) '
        'and scored with live rainfall + terrain risk. They are indicative only. '
        'Always check IMD, USDMC Uttarakhand, GSI and district administration for official road status.</p>'
    )
    return '<div class="sb-stack">' + header + cards + note + '</div>'


def safe_routes(odist, otown, ddist, dtown):
    try:
        load_data()
    except Exception as e:
        return err_box(e), ""

    orig_key = (odist, otown)
    dest_key = (ddist, dtown)
    if orig_key not in INDEX:
        orig_key = (odist, TOWNS[odist][0][0])
    if dest_key not in INDEX:
        dest_key = (ddist, TOWNS[ddist][0][0])

    routes = find_route_options(orig_key, dest_key)

    show_places = set([orig_key, dest_key])
    path_coords = []

    for r in routes:
        for k in r["path"]:
            show_places.add(k)

        # Try to get a real, road-following path through this route's towns.
        geom, road_km, road_min = mapbox_road_route(r["places"])
        if geom:
            r["road_km"] = road_km
            r["road_min"] = road_min
            path_coords.append(geom)
        else:
            r["road_km"] = None
            r["road_min"] = None
            coords = [[INDEX[k]["lon"], INDEX[k]["lat"]] for k in r["path"]]
            if len(coords) >= 2:
                path_coords.append(coords)

    places_on_map = [INDEX[k] for k in show_places]

    hs = []
    for h in HOTSPOTS:
        for p in places_on_map:
            if haversine(h[2], h[3], p["lat"], p["lon"]) < 45:
                hs.append(h)
                break

    o = INDEX[orig_key]
    d = INDEX[dest_key]
    center = [(o["lat"] + d["lat"]) / 2, (o["lon"] + d["lon"]) / 2]
    dist_km = haversine(o["lat"], o["lon"], d["lat"], d["lon"])
    zoom = 9 if dist_km < 80 else (8 if dist_km < 160 else 7)

    m = build_map(
        places_on_map,
        hs,
        center=center,
        zoom=zoom,
        selected=None,
        highlight_keys=show_places,
        paths=path_coords,
    )
    return route_report_html(orig_key, dest_key, routes), m


# =====================================================================
# HTML BUILDERS
# =====================================================================
def card(label, value, icon):
    return (
        '<div class="sb-metric">'
        f'<div class="sb-metric-l">{icon} {label}</div>'
        f'<div class="sb-metric-v">{value}</div></div>'
    )


def rain_chart(dates, rain):
    mx = max(max(rain), 1)
    bars = ""
    for i, (dt, r) in enumerate(zip(dates, rain)):
        h = max(int(r / mx * 90), 3)
        col = "#c3cfd8" if i < 3 else "linear-gradient(180deg,#7ed3a8,#2f9e7a)"
        bars += (
            '<div class="sb-bar">'
            '<div class="sb-bar-track">'
            f'<div style="width:64%;height:{h}px;background:{col};border-radius:7px 7px 0 0"></div></div>'
            f'<b>{r:.0f}</b><span>{dt[5:]}</span></div>'
        )
    return (
        '<div class="sb-panel">'
        '<div class="sb-panel-h"><span>🌧️ Rainfall (mm)</span>'
        '<small>grey = last 3 days · green = forecast</small></div>'
        f'<div class="sb-bars">{bars}</div></div>'
    )


# =====================================================================
# PLACE REPORT
# =====================================================================
def place_report_html(p):
    wx = p["wx"]
    r = p["risk"]
    cur = wx["current"]
    daily = wx["daily"]
    lvl = r["level"]
    name, label, color = LEVELS[lvl]
    title, advice = TRAVEL[lvl]
    cond = WEATHER_CODES.get(cur["weather_code"], "N/A")
    fg = "#3b2f00" if lvl == 1 else "#ffffff"

    banner = (
        f'<div class="sb-banner" style="background:linear-gradient(135deg,{color},{color}cc);color:{fg}">'
        f'<div class="sb-banner-s">{H.escape(p["name"])}, {H.escape(p["district"])} district</div>'
        f'<div class="sb-banner-t">Landslide risk: {name} ({label})</div></div>'
    )

    reasons = "".join(f"<li>{x}</li>" for x in r["reasons"])
    notes = "".join(f"<li>{x}</li>" for x in travel_notes(p))

    travel = (
        f'<div class="sb-panel" style="border-left:6px solid {color}">'
        f'<div class="sb-panel-h"><span>🧳 Is it safe to travel? {title}</span></div>'
        f'<p class="sb-p">{advice}</p>'
        f'<div class="sb-sub">Why this rating</div><ul class="sb-ul">{reasons}</ul>'
        f'<div class="sb-sub">Travel tips</div><ul class="sb-ul">{notes}</ul></div>'
    )

    weather = (
        '<div class="sb-panel">'
        f'<div class="sb-temp">{cur["temperature_2m"]} °C '
        f'<span>{cond}</span></div>'
        f'<div class="sb-muted">Feels like {cur["apparent_temperature"]} °C</div>'
        '<div class="sb-metrics">'
        + card("Humidity", f'{cur["relative_humidity_2m"]}%', "💧")
        + card("Wind", f'{cur["wind_speed_10m"]} km/h', "🌬️")
        + card("Gusts", f'{cur["wind_gusts_10m"]} km/h', "💨")
        + card("Pressure", f'{cur["pressure_msl"]} hPa', "🧭")
        + card("Cloud cover", f'{cur["cloud_cover"]}%', "☁️")
        + card("Rain now", f'{cur["precipitation"]} mm', "🌧️")
        + card("UV today", daily["uv_index_max"][3], "🕶️")
        + card("Elevation", f'{r["elev"]:.0f} m', "⛰️")
        + card("Sunrise", daily["sunrise"][3][-5:], "🌅")
        + card("Sunset", daily["sunset"][3][-5:], "🌇")
        + '</div></div>'
    )

    chart = rain_chart(daily["time"], [(x or 0) for x in daily["precipitation_sum"]])

    rows = ""
    for i in range(3, 10):
        rr = daily["precipitation_sum"][i] or 0
        dl = day_level(rr, r["terrain"])
        rows += (
            '<tr>'
            f'<td><b>{daily["time"][i]}</b></td>'
            f'<td>{WEATHER_CODES.get(daily["weather_code"][i], "-")}</td>'
            f'<td>{daily["temperature_2m_min"][i]}° / {daily["temperature_2m_max"][i]}°</td>'
            f'<td>{rr:.1f} mm</td>'
            f'<td>{daily["precipitation_probability_max"][i] or 0}%</td>'
            f'<td>{chip(dl)}</td></tr>'
        )

    forecast = (
        '<div class="sb-panel" style="overflow-x:auto">'
        '<div class="sb-panel-h"><span>📅 7-day forecast</span></div>'
        '<table class="sb-table"><thead><tr>'
        '<th>Date</th><th>Weather</th><th>Min / Max</th><th>Rain</th><th>Chance</th><th>Slide risk</th>'
        f'</tr></thead><tbody>{rows}</tbody></table></div>'
    )

    hs = [h for h in HOTSPOTS if h[1] == p["district"]]
    if hs:
        items = ""
        for n, dist, la, lo, base in hs:
            near = nearest_place(la, lo)
            items += (
                f'<li>{H.escape(n)} — usually <b>{base}</b> susceptibility, '
                f'right now {chip(near["risk"]["level"])}</li>'
            )
        hot = (
            '<div class="sb-panel">'
            '<div class="sb-panel-h"><span>⚠️ Known landslide-prone spots in this district</span></div>'
            f'<ul class="sb-ul" style="line-height:2">{items}</ul></div>'
        )
    else:
        hot = ""

    note = (
        '<p class="sb-note">This rating is a simple rainfall-and-terrain indicator, not an official warning. '
        'Always check IMD, USDMC Uttarakhand, GSI and district administration alerts before travelling.</p>'
    )
    return '<div class="sb-stack">' + banner + travel + weather + chart + forecast + hot + note + '</div>'


# =====================================================================
# MAP  —  3D interactive (MapLibre GL JS) with route lines + on-screen error box
# =====================================================================
def build_map(
    places,
    hotspots,
    center=None,
    zoom=7,
    selected=None,
    highlight_keys=None,
    paths=None,
):
    if center is None:
        center = [30.0, 79.1]
    if highlight_keys is None:
        highlight_keys = set()
    if paths is None:
        paths = []

    marker_data = []
    for p in places:
        r = p["risk"]
        key = (p["district"], p["name"])
        is_sel = (selected is p) or (key in highlight_keys)
        marker_data.append({
            "name": p["name"],
            "district": p["district"],
            "lat": p["lat"],
            "lon": p["lon"],
            "risk": LEVELS[r["level"]][0],
            "riskLabel": LEVELS[r["level"]][1],
            "color": LEVELS[r["level"]][2],
            "past3": round(r["past3"]),
            "next3": round(r["next3"]),
            "travel": TRAVEL[r["level"]][0],
            "selected": bool(is_sel),
        })

    hotspot_data = []
    for n, dist, la, lo, base in hotspots:
        lv = nearest_place(la, lo)["risk"]["level"]
        hotspot_data.append({
            "name": n, "district": dist, "lat": la, "lon": lo,
            "base": base, "risk": LEVELS[lv][0], "color": LEVELS[lv][2],
        })

    data_json = json.dumps({"places": marker_data, "hotspots": hotspot_data}, ensure_ascii=False).replace("</", "<\\/")
    paths_json = json.dumps(paths).replace("</", "<\\/")
    center_json = json.dumps([float(center[1]), float(center[0])])
    token_json = json.dumps(MAPBOX_TOKEN or "")

    legend_html = """
    <div id="legend">
      <b>Landslide risk</b><br>
      <span style="color:#2e9e5b">●</span> Green - low<br>
      <span style="color:#d4a800">●</span> Yellow - moderate<br>
      <span style="color:#f28c28">●</span> Orange - high<br>
      <span style="color:#d63a3a">●</span> Red - very high<br>
      <span style="color:#0ea5e9">━</span> Suggested route<br>
      <span style="color:#d63a3a">⚠</span> Known landslide-prone spot
    </div>
    """

    html_doc = f"""
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<link href="https://unpkg.com/maplibre-gl@3.6.2/dist/maplibre-gl.css" rel="stylesheet">
<style>
html, body {{ margin:0; padding:0; width:100%; height:100%; overflow:hidden; font-family:Arial,sans-serif; }}
#map {{ position:absolute; inset:0; width:100%; height:100%; }}
#title {{
    position:absolute; top:12px; left:12px; z-index:10;
    background:rgba(255,255,255,.94); padding:8px 12px; border-radius:10px;
    box-shadow:0 2px 8px rgba(0,0,0,.22); font-size:14px; font-weight:800; color:#1f2937;
}}
#legend {{
    position:absolute; bottom:18px; left:12px; z-index:10;
    background:rgba(255,255,255,.96); padding:10px 14px; border-radius:10px;
    box-shadow:0 2px 8px rgba(0,0,0,.22); font-size:13px; line-height:1.55; color:#222; font-weight:600;
}}
#err-box {{
    position:absolute; top:12px; right:12px; left:auto; z-index:20; max-width:340px;
    background:#fff3cd; color:#664d03; padding:10px 14px; border-radius:10px;
    box-shadow:0 2px 10px rgba(0,0,0,.3); font-size:12px; font-weight:700; display:none;
    white-space:pre-wrap;
}}
.marker {{
    width:20px; height:20px; border-radius:50%; border:2.5px solid white;
    box-shadow:0 2px 6px rgba(0,0,0,.5); cursor:pointer;
}}
.marker.selected {{
    width:32px; height:32px; border:3.5px solid #111;
    box-shadow:0 0 0 3px rgba(14,165,233,.55), 0 2px 8px rgba(0,0,0,.55);
}}
.hotspot {{
    width:28px; height:28px; border-radius:50%; border:2px solid #222; color:white;
    display:flex; align-items:center; justify-content:center;
    font-weight:bold; font-size:16px; box-shadow:0 1px 5px rgba(0,0,0,.45); cursor:pointer;
}}
.maplibregl-popup-content {{ color:#1f2937; font-size:13px; line-height:1.5; border-radius:10px; font-weight:600; }}
</style>
</head>
<body>
<div id="map"></div>
<div id="title">🛰️ 3D Satellite — Uttarakhand Weather &amp; Landslide Risk</div>
<div id="err-box"></div>
{legend_html}
<script src="https://unpkg.com/maplibre-gl@3.6.2/dist/maplibre-gl.js"></script>
<script>
function showError(msg) {{
    var box = document.getElementById("err-box");
    box.style.display = "block";
    box.textContent = "⚠️ Map error: " + msg;
}}
window.onerror = function(msg) {{ showError(msg); return false; }};

try {{
    const DATA = {data_json};
    const PATHS = {paths_json};
    const CENTER = {center_json};
    const ZOOM = {float(zoom)};
    const MAPBOX_TOKEN = {token_json};

    if (!MAPBOX_TOKEN) {{
        showError("No Mapbox token found. Add a Colab Secret named MAPBOX_TOKEN with your Mapbox access token (starts with 'pk.'), turn on Notebook access, then rerun the app cell.");
    }}

    const STYLE = {{
        version: 8,
        sources: {{
            satellite: {{
                type: "raster",
                tiles: ["https://api.mapbox.com/v4/mapbox.satellite/{{z}}/{{x}}/{{y}}@2x.jpg90?access_token=" + MAPBOX_TOKEN],
                tileSize: 256,
                attribution: "© Mapbox © Maxar"
            }},
            terrainSource: {{
                type: "raster-dem",
                tiles: ["https://api.mapbox.com/v4/mapbox.terrain-rgb/{{z}}/{{x}}/{{y}}.pngraw?access_token=" + MAPBOX_TOKEN],
                tileSize: 256,
                encoding: "mapbox",
                maxzoom: 14
            }}
        }},
        layers: [
            {{ id: "satellite-layer", type: "raster", source: "satellite" }}
        ]
    }};

    const map = new maplibregl.Map({{
        container: "map",
        style: STYLE,
        center: CENTER,
        zoom: ZOOM,
        pitch: 55,
        bearing: -15,
        maxPitch: 85,
        antialias: true
    }});

    map.addControl(new maplibregl.NavigationControl({{visualizePitch: true}}), "top-right");
    map.addControl(new maplibregl.ScaleControl({{maxWidth: 120, unit: "metric"}}), "bottom-right");

    function escapeHtml(value) {{
        return String(value)
            .replaceAll("&", "&amp;")
            .replaceAll("<", "&lt;")
            .replaceAll(">", "&gt;")
            .replaceAll('"', "&quot;")
            .replaceAll("'", "&#039;");
    }}

    function addMarkers() {{
        DATA.places.forEach(p => {{
            const el = document.createElement("div");
            el.className = "marker" + (p.selected ? " selected" : "");
            el.style.background = p.color;

            const popup = new maplibregl.Popup({{offset: 16}}).setHTML(
                "<b>" + escapeHtml(p.name) + "</b><br>" +
                escapeHtml(p.district) + " district<br>" +
                "Risk: <b>" + escapeHtml(p.risk) + " (" + escapeHtml(p.riskLabel) + ")</b><br>" +
                "Rain last 3 days: " + p.past3 + " mm<br>" +
                "Rain next 3 days: " + p.next3 + " mm<br>" +
                escapeHtml(p.travel)
            );

            new maplibregl.Marker({{element: el}})
                .setLngLat([p.lon, p.lat])
                .setPopup(popup)
                .addTo(map);

            if (p.selected) popup.addTo(map);
        }});

        DATA.hotspots.forEach(h => {{
            const el = document.createElement("div");
            el.className = "hotspot";
            el.style.background = h.color;
            el.innerHTML = "⚠";

            const popup = new maplibregl.Popup({{offset: 16}}).setHTML(
                "<b>⚠️ " + escapeHtml(h.name) + "</b><br>" +
                escapeHtml(h.district) + " district<br>" +
                "Usual susceptibility: <b>" + escapeHtml(h.base) + "</b><br>" +
                "Current app risk nearby: <b>" + escapeHtml(h.risk) + "</b>"
            );

            new maplibregl.Marker({{element: el}})
                .setLngLat([h.lon, h.lat])
                .setPopup(popup)
                .addTo(map);
        }});
    }}

    function addRouteLines() {{
        if (!PATHS || PATHS.length === 0) return;
        const features = PATHS.map(coords => ({{
            type: "Feature",
            geometry: {{ type: "LineString", coordinates: coords }}
        }}));

        map.addSource("routes", {{
            type: "geojson",
            data: {{ type: "FeatureCollection", features: features }}
        }});

        map.addLayer({{
            id: "route-lines-casing",
            type: "line",
            source: "routes",
            paint: {{ "line-color": "#0c4a6e", "line-width": 7, "line-opacity": 0.35 }}
        }});

        map.addLayer({{
            id: "route-lines",
            type: "line",
            source: "routes",
            paint: {{ "line-color": "#0ea5e9", "line-width": 4.5, "line-opacity": 0.92 }}
        }});
    }}

    map.on("load", () => {{
        try {{
            map.addSource("terrainSource", {{
                type: "raster-dem",
                tiles: ["https://api.mapbox.com/v4/mapbox.terrain-rgb/{{z}}/{{x}}/{{y}}.pngraw?access_token=" + MAPBOX_TOKEN],
                tileSize: 256,
                encoding: "mapbox",
                maxzoom: 14
            }});
        }} catch (e) {{ /* source may already exist from style */ }}
        try {{
            map.setTerrain({{ source: "terrainSource", exaggeration: 1.35 }});
        }} catch (e) {{
            showError("Terrain unavailable, showing flat map. (" + e.message + ")");
        }}
        addRouteLines();
        addMarkers();
    }});

    map.on("error", (e) => {{
        if (e && e.error) showError(e.error.message || String(e.error));
    }});

}} catch (e) {{
    showError(e.message || String(e));
}}
</script>
</body>
</html>
"""

    return (
        f'<iframe srcdoc="{H.escape(html_doc, quote=True)}" '
        'style="width:100%;height:620px;border:none;border-radius:16px"></iframe>'
    )


# =====================================================================
# ERRORS
# =====================================================================
def err_box(e):
    return (
        '<div class="sb-warnbox">'
        f'⚠️ Could not fetch weather data. Please try again.<br><code>{H.escape(str(e))}</code></div>'
    )


# =====================================================================
# APP FUNCTIONS
# =====================================================================
def on_district(d):
    names = [t[0] for t in TOWNS[d]]
    return gr.Dropdown(choices=names, value=names[0])


def report(district, town):
    try:
        load_data()
    except Exception as e:
        return err_box(e), ""

    p = INDEX.get((district, town)) or INDEX[(district, TOWNS[district][0][0])]
    hs = [h for h in HOTSPOTS if h[1] == district]

    m = build_map(
        PLACES, hs,
        center=[p["lat"], p["lon"]],
        zoom=10,
        selected=p
    )
    return place_report_html(p), m


def overview(sel_districts, sel_levels):
    try:
        load_data()
    except Exception as e:
        return err_box(e), ""

    if not sel_districts:
        return "<p>Please select at least one district.</p>", ""

    rows = []
    counts = [0, 0, 0, 0]
    keep = []

    for d in sel_districts:
        pl = [p for p in PLACES if p["district"] == d]
        worst = max(pl, key=lambda p: (p["risk"]["level"], p["risk"]["index"]))
        lv = worst["risk"]["level"]
        if LEVELS[lv][0] not in sel_levels:
            continue
        keep.append(d)
        counts[lv] += 1
        avg3 = sum(p["risk"]["next3"] for p in pl) / len(pl)
        avgp = sum(p["risk"]["past3"] for p in pl) / len(pl)
        rows.append((lv, d, worst, avg3, avgp))

    rows.sort(key=lambda x: -x[0])

    summary = "".join(
        f'<span style="margin-right:8px">{chip(i, f"{LEVELS[i][0]}: {counts[i]}")}</span>'
        for i in range(4)
    )

    body = ""
    for lv, d, worst, avg3, avgp in rows:
        body += (
            '<tr>'
            f'<td><b>{H.escape(d)}</b></td>'
            f'<td>{chip(lv)}</td>'
            f'<td>{H.escape(worst["name"])}</td>'
            f'<td>{avgp:.0f} mm</td>'
            f'<td>{avg3:.0f} mm</td>'
            f'<td>{TRAVEL[lv][0]}</td></tr>'
        )

    if not body:
        body = '<tr><td colspan="6">No districts match this selection.</td></tr>'

    html = (
        '<div class="sb-panel" style="overflow-x:auto">'
        f'<div style="margin-bottom:12px">{summary}</div>'
        '<table class="sb-table"><thead><tr>'
        '<th>District</th><th>Risk</th><th>Most at-risk area</th>'
        '<th>Past 3 days (avg rain)</th><th>Next 3 days (avg rain)</th><th>Travel</th></tr></thead>'
        f'<tbody>{body}</tbody></table></div>'
    )

    places = [p for p in PLACES if p["district"] in keep]
    hs = [h for h in HOTSPOTS if h[1] in keep]
    return html, build_map(places, hs, zoom=7)


# =====================================================================
# GEMINI AI ASSISTANT
# =====================================================================
SYSTEM_RULES = (
    "You are a careful weather and travel-safety assistant for Uttarakhand, India. "
    "Use ONLY the data provided below. Do not invent road closures, alerts or numbers. "
    "Answer in simple, clear language, keep it short (under 200 words), and use bullet points where helpful. "
    "The risk colour is a simple app estimate based on rainfall and terrain, not an official warning. "
    "Always end with a one-line reminder to check IMD and the district administration for official alerts."
)


def ask_gemini(prompt):
    if client is None:
        return (
            "⚠️ Gemini API key not found. "
            "In Colab, click the 🔑 Secrets icon, add a secret named "
            "`GEMINI_API_KEY`, turn on Notebook access, then run this cell again."
        )
    try:
        resp = client.models.generate_content(model=GEMINI_MODEL, contents=prompt)
        return resp.text or "The AI returned an empty answer. Please try again."
    except Exception as e:
        return f"⚠️ AI assistant error: {e}"


def ai_explain(district, town, question):
    try:
        load_data()
    except Exception as e:
        return f"⚠️ Could not fetch weather data: {e}"

    p = INDEX.get((district, town)) or INDEX[(district, TOWNS[district][0][0])]
    r = p["risk"]
    d = p["wx"]["daily"]
    cur = p["wx"]["current"]
    hs = [f"{h[0]} (usual susceptibility: {h[4]})" for h in HOTSPOTS if h[1] == p["district"]]

    facts = (
        f"Place: {p['name']}, {p['district']} district\n"
        f"App landslide risk: {LEVELS[r['level']][0]} ({LEVELS[r['level']][1]})\n"
        f"Current: {cur['temperature_2m']} C, {WEATHER_CODES.get(cur['weather_code'], 'n/a')}, "
        f"wind {cur['wind_speed_10m']} km/h, humidity {cur['relative_humidity_2m']}%\n"
        f"Rain last 3 days: {r['past3']:.0f} mm; next 3 days: {r['next3']:.0f} mm; "
        f"next 7 days: {r['next7']:.0f} mm; heaviest day: {r['peak']:.0f} mm\n"
        f"Daily rain forecast (mm, from today): {[round(x or 0, 1) for x in d['precipitation_sum'][3:10]]}\n"
        f"Max temps next 3 days: {d['temperature_2m_max'][3:6]}\n"
        f"Terrain: {r['terrain_name']} ({r['elev']:.0f} m)\n"
        f"Known landslide-prone spots in the district: {'; '.join(hs) or 'none listed'}\n"
        f"App travel verdict: {TRAVEL[r['level']][0]}\n"
        f"Travel notes: {' | '.join(travel_notes(p))}"
    )

    q = (question or "").strip() or (
        "Give a short summary of the weather and landslide risk, and say whether travel looks advisable."
    )
    return ask_gemini(f"{SYSTEM_RULES}\n\nDATA:\n{facts}\n\nQUESTION: {q}")


def ai_overview(sel_districts):
    try:
        load_data()
    except Exception as e:
        return f"⚠️ Could not fetch weather data: {e}"

    if not sel_districts:
        return "Please select at least one district."

    lines = []
    for d in sel_districts:
        pl = [p for p in PLACES if p["district"] == d]
        worst = max(pl, key=lambda p: (p["risk"]["level"], p["risk"]["index"]))
        r = worst["risk"]
        lines.append(
            f"{d}: risk {LEVELS[r['level']][0]} (most at-risk place: {worst['name']}), "
            f"rain last 3 days {r['past3']:.0f} mm, next 3 days {r['next3']:.0f} mm"
        )

    prompt = (
        f"{SYSTEM_RULES}\n\nDATA (one line per district):\n"
        + "\n".join(lines)
        + "\n\nQUESTION: Summarise the situation across these districts. "
        "Which are worst, which are safest, and what general travel advice applies?"
    )
    return ask_gemini(prompt)


# =====================================================================
# SAFEBHOOMI HERO + STATEWIDE SITUATION OVERVIEW
# =====================================================================
def compute_state_stats():
    try:
        load_data()
    except Exception:
        return dict(critical=0, high=0, alerts=0, avg=0, ok=False, top=[])

    worst_rows = []
    for d in DISTRICTS:
        pl = [p for p in PLACES if p["district"] == d]
        worst = max(pl, key=lambda p: (p["risk"]["level"], p["risk"]["index"]))
        worst_rows.append((d, worst))

    levels = [w["risk"]["level"] for _, w in worst_rows]
    critical = sum(1 for lv in levels if lv == 3)
    high = sum(1 for lv in levels if lv == 2)
    alerts = sum(1 for lv in levels if lv >= 1)
    avg_pct = round(100 * sum(p["risk"]["level"] for p in PLACES) / (3 * len(PLACES)))
    top = sorted(worst_rows, key=lambda x: (-x[1]["risk"]["level"], -x[1]["risk"]["index"]))[:5]
    return dict(critical=critical, high=high, alerts=alerts, avg=avg_pct, ok=True, top=top)


